import sys

data = sys.stdin.read().split()
target, fuel, n = int(data[0]), int(data[1]), int(data[2])
st = [(int(data[3 + 2 * i]), int(data[4 + 2 * i])) for i in range(n)]
dp = [-1] * (n + 1)
dp[0] = fuel
for pos, f in st:
    for k in range(n - 1, -1, -1):
        if dp[k] >= pos:
            dp[k + 1] = max(dp[k + 1], dp[k] + f)
ans = -1
for k in range(n + 1):
    if dp[k] >= target:
        ans = k
        break
print(ans)

